          {...propsExtracted.inputProps}
          ref={mergeRefs(inputRef, inputProps?.ref, ref)}
          type={type}
          className={cx(cl['bk-input__input'], inputProps?.className)}
        />
        {actions}
      </span>
    );
  },
  {
    Action: InputAction,
  },
);

