  return (
    <>
      <div
        {...scrollProps}
        ref={scrollWrapperRef}
        className={cx(cl['bk-data-table-container'], {
            [cl['bk-data-table-container--scrolled-left']]: overflowPosition === 'left'
              || overflowPosition === 'center',
